    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
        {
            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var sf) && s.Status != sf)
                return false;

            if (!string.IsNullOrWhiteSpace(searchTerm))
            {
                var term = searchTerm.Trim();
                return s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase)
                    || s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase)
                    || s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase);
            }

            return true;
        });

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (e.Value is string val && int.TryParse(val, out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            await LoadShipments();
        }
